 27→/**
 28→ * Convert ExportedTask to TaskSummary
 29→ */
 30→function toTaskSummary(task: ExportedTask): TaskSummary {
 31→	return {
 32→		_ulid: task._ulid,
 33→		slugs: task.slugs,
 34→		title: task.title,
 35→		type: task.type,
 36→		status: task.status,
 37→		priority: task.priority,
 38→		spec_ref: task.spec_ref ?? undefined,
 39→		tags: task.tags,
 40→		depends_on: task.depends_on,
 41→		created_at: task.created_at,
 42→		started_at: task.started_at ?? undefined,
 43→		notes_count: task.notes?.length ?? 0,
 44→		todos_count: task.todos?.length ?? 0
 45→	};
 46→}
 47→
 48→/**
 49→ * Convert ExportedItem to ItemSummary
 50→ */
 51→function toItemSummary(item: ExportedItem): ItemSummary {
 52→	return {
 53→		_ulid: item._ulid,
 54→		slugs: item.slugs,
 55→		title: item.title,
 56→		type: item.type,
 57→		status: item.status,
 58→		tags: item.tags,
 59→		created_at: item.created_at ?? new Date().toISOString()
 60→	};
 61→}
 62→
 63→/**
 64→ * Filter helper for tasks
 65→ */
 66→function filterTasks(
 67→	tasks: ExportedTask[],
 68→	params?: {
 69→		status?: string;
 70→		type?: string;
 71→		tag?: string;
 72→		assignee?: string;
 73→		automation?: string;
 74→	}
 75→): ExportedTask[] {
 76→	let result = tasks;
 77→
 78→	if (params?.status) {
 79→		result = result.filter((t) => t.status === params.status);
 80→	}
 81→	if (params?.type) {
 82→		result = result.filter((t) => t.type === params.type);
 83→	}
 84→	if (params?.tag) {
 85→		result = result.filter((t) => t.tags.includes(params.tag!));
 86→	}
 87→	if (params?.assignee) {
 88→		result = result.filter((t) => t.assignee === params.assignee);
 89→	}
 90→	if (params?.automation) {
 91→		result = result.filter((t) => t.automation === params.automation);
 92→	}
 93→
 94→	return result;
 95→}
 96→
 97→/**
 98→ * Filter helper for items
 99→ */
100→function filterItems(
101→	items: ExportedItem[],
102→	params?: {
103→		type?: string | string[];
104→		tag?: string;
105→	}
106→): ExportedItem[] {
107→	let result = items;
108→
109→	if (params?.type) {
110→		const types = Array.isArray(params.type) ? params.type : [params.type];
111→		result = result.filter((i) => types.includes(i.type));
112→	}
113→	if (params?.tag) {
114→		result = result.filter((i) => i.tags.includes(params.tag!));
115→	}
116→
117→	return result;
118→}
