120→/**
121→ * Paginate array
122→ */
123→function paginate<T>(
124→	items: T[],
125→	params?: { limit?: number; offset?: number }
126→): PaginatedResponse<T> {
127→	const limit = params?.limit ?? 50;
128→	const offset = params?.offset ?? 0;
129→	const paged = items.slice(offset, offset + limit);
130→
131→	return {
132→		items: paged,
133→		total: items.length,
134→		offset,
135→		limit
136→	};
137→}
