206→/**
207→ * Fetch single task from static snapshot
208→ * AC: @gh-pages-export ac-12
209→ */
210→export function fetchTaskStatic(ref: string): TaskDetail | null {
211→	const snapshot = getSnapshot();
212→	if (!snapshot) return null;
213→
214→	const task = findTaskByRef(snapshot.tasks, ref);
215→	if (!task) return null;
216→
217→	// ExportedTask extends TaskDetail, so we can return it directly
218→	return task;
219→}
