221→/**
222→ * Fetch items from static snapshot
223→ * AC: @gh-pages-export ac-11
224→ */
225→export function fetchItemsStatic(params?: {
226→	type?: string | string[];
227→	tag?: string;
228→	limit?: number;
229→	offset?: number;
230→}): PaginatedResponse<ItemSummary> {
231→	const snapshot = getSnapshot();
232→	if (!snapshot) {
233→		return { items: [], total: 0, offset: 0, limit: 50 };
234→	}
