     1→/**
     2→ * Plans API Routes
     3→ *
     4→ * REST endpoints for plan operations:
     5→ * - GET /api/plans - list plans with status filter and task progress
     6→ *
     7→ * AC Coverage:
     8→ * - @ui-plans-view ac-1: Plan list with title, status, dates, linked counts, progress
     9→ */
    10→
    11→import { Elysia, t } from 'elysia';
    12→import {
    13→  initContext,
    14→  loadPlans,
    15→  loadAllTasks,
    16→  type LoadedPlan,
    17→} from '../../parser/index.js';
    18→import type { PlanSummary } from '@kynetic-ai/shared';
    19→
    20→interface PlansRouteOptions {}
    21→
    22→export function createPlansRoutes(options: PlansRouteOptions = {}) {
    23→  return new Elysia({ prefix: '/api/plans' })
    24→    // AC: @ui-plans-view ac-1 - List plans with progress
    25→    .get(
    26→      '/',
    27→      async ({ query, projectContext }) => {
    28→        const ctx = await initContext(projectContext.path);
    29→        const plans = await loadPlans(ctx);
    30→        const tasks = await loadAllTasks(ctx);
    31→
    32→        // Build a task status lookup by ref (ULID or slug)
    33→        const tasksByRef = new Map<string, { status: string }>();
    34→        for (const task of tasks) {
    35→          tasksByRef.set(task._ulid, { status: task.status });
    36→          for (const slug of task.slugs) {
    37→            tasksByRef.set(slug, { status: task.status });
    38→          }
    39→        }
    40→
    41→        // Apply status filter
    42→        let filtered: LoadedPlan[] = plans;
    43→        if (query.status) {
    44→          const statusFilters = Array.isArray(query.status) ? query.status : [query.status];
    45→          filtered = filtered.filter((plan) => statusFilters.includes(plan.status));
    46→        }
    47→
    48→        // Sort by created_at descending (newest first)
    49→        const sorted = [...filtered].sort(
    50→          (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
    51→        );
    52→
    53→        // AC: @ui-plans-view ac-1 - Compute progress for each plan
    54→        const items: PlanSummary[] = sorted.map((plan) => {
    55→          const progress = { total: 0, completed: 0, in_progress: 0, pending: 0, blocked: 0 };
    56→
    57→          for (const ref of plan.derived_tasks) {
    58→            const cleanRef = ref.startsWith('@') ? ref.slice(1) : ref;
    59→            const task = tasksByRef.get(cleanRef);
    60→            if (task) {
    61→              progress.total++;
    62→              if (task.status === 'completed') progress.completed++;
    63→              else if (task.status === 'in_progress' || task.status === 'pending_review' || task.status === 'needs_work') progress.in_progress++;
    64→              else if (task.status === 'blocked') progress.blocked++;
    65→              else progress.pending++;
    66→            }
    67→          }
    68→
    69→          return {
    70→            _ulid: plan._ulid,
    71→            slugs: plan.slugs,
    72→            title: plan.title,
    73→            status: plan.status,
    74→            created_at: plan.created_at,
    75→            approved_at: plan.approved_at ?? undefined,
    76→            completed_at: plan.completed_at ?? undefined,
    77→            derived_specs: plan.derived_specs,
    78→            derived_tasks: plan.derived_tasks,
    79→            spec_count: plan.derived_specs.length,
    80→            task_count: plan.derived_tasks.length,
    81→            task_progress: progress,
    82→          };
    83→        });
    84→
    85→        return {
    86→          items,
    87→          total: items.length,
    88→        };
    89→      },
