### 4. E2E Test Patterns

#### Pattern 1: Basic Page Load & Visibility
```typescript
test('page loads and shows sidebar', async ({ page, daemon }) => {
  await page.goto('/');
  await expect(page.getByTestId('sidebar-nav')).toBeVisible();
  await expect(page.getByTestId('connection-status')).toContainText(/connected/i);
});
```

#### Pattern 2: List with Filters
```typescript
test('filters tasks by status', async ({ page, daemon }) => {
  await page.goto('/tasks');

  // Wait for list to load
  const taskList = page.getByTestId('task-list');
  await expect(taskList).toBeVisible();

  // Apply filter
  const filterStatus = page.getByTestId('filter-status');
  await filterStatus.click();
  await page.getByRole('option', { name: 'Pending', exact: true }).click();

  // Verify URL updates
  await page.waitForURL(/status=pending/, { timeout: 10000 });

  // Verify results
  const taskItems = page.getByTestId('task-list-item');
  const count = await taskItems.count();
  for (let i = 0; i < count; i++) {
    const statusBadge = taskItems.nth(i).getByTestId('task-status-badge');
    await expect(statusBadge).toContainText(/pending/i);
  }
});
```

#### Pattern 3: Detail Panel / Sheet Interaction
```typescript
test('opens detail panel when task clicked', async ({ page, daemon }) => {
  await page.goto('/tasks');

  // Wait for list
  const taskList = page.getByTestId('task-list');
  const taskItem = taskList.getByTestId('task-list-item').first();
  await expect(taskItem).toBeVisible();

  // Click to open detail
  await taskItem.click();
  await page.waitForTimeout(2000); // Wait for sheet animation

  // Verify panel
  const detailPanel = page.getByTestId('task-detail-panel');
  await expect(detailPanel).toBeVisible({ timeout: 5000 });

  // Check panel contents
  await expect(detailPanel.getByTestId('task-description')).toBeVisible();
  await expect(detailPanel.getByTestId('task-notes')).toBeVisible();
});
```

#### Pattern 4: Form Submission
```typescript
test('adds note to task', async ({ page, daemon }) => {
  await page.goto('/tasks');
  const taskItem = page.getByTestId('task-list-item').first();
  await taskItem.click();

  const detailPanel = page.getByTestId('task-detail-panel');
  const addNoteForm = detailPanel.getByTestId('add-note-form');

  // Fill form
  const noteTextarea = addNoteForm.getByTestId('note-textarea');
  await noteTextarea.fill('Test note content');

  // Intercept API request
  const requestPromise = page.waitForRequest((request) => {
    return request.url().includes('/api/tasks/') && request.url().includes('/note');
  });

  // Submit
  const submitButton = addNoteForm.getByTestId('add-note-button');
  await submitButton.click();

  // Verify API call
  const request = await requestPromise;
  expect(request.method()).toBe('POST');

  // Verify UI update
  const notesSection = detailPanel.getByTestId('task-notes');
  await expect(notesSection).toContainText('Test note content');
  await expect(noteTextarea).toHaveValue('');
});
```

#### Pattern 5: Listing Items with Iteration
```typescript
test('displays triage status badge for each inbox item', async ({ page }) => {
  const inboxList = page.getByTestId('inbox-list');
  await expect(inboxList).toBeVisible({ timeout: 10000 });

  const items = page.getByTestId('inbox-item');
  const count = await items.count();
  expect(count).toBeGreaterThan(0);

  // Iterate through all items
  for (let i = 0; i < count; i++) {
    const item = items.nth(i);
    const statusBadge = item.getByTestId('inbox-triage-status');
    await expect(statusBadge).toBeVisible();

    const statusText = await statusBadge.textContent();
    expect(['Untriaged', 'Triaged', 'Acted On']).toContain(statusText?.trim());
  }
});
```

