 43→      if (result.stdout.trim()) {
 44→        const pids = result.stdout.trim().split('\n');
 45→        for (const pid of pids) {
 46→          try {
 47→            process.kill(parseInt(pid, 10), 'SIGTERM');
 48→          } catch {
 49→            // Process may already be gone
 50→          }
 51→        }
 52→      }
 53→    }
 54→    await new Promise((r) => setTimeout(r, 1000));
 55→  } catch {
 56→    // Command may not be available on all systems
 57→  }
 58→}
